let state;try{state=JSON.parse(localStorage.getItem(key)||'null');}catch{}if(!state||!state.company||!Array.isArray(state.vehicles))state=structuredClone(initial);
let page=['overview','agents','conversations','inventory','sites','integrations','reports','billing','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
